/* bitGen Studio — lib/sceneAI.js (2.404.0): ✨ BUILD A SCENE WITH AI - words -> a .blend open in the preview canvas.
 *
 * Tim (verbatim): "is it possible for our llm to use blender to create 3d models?" -> "can we add option 1 + the image
 * to workflow?" (option 1 = the LLM's JSON plan built in Blender; the image half = detailed objects from a picture).
 * His answers: Hunyuan3D by default, TRELLIS.2 as the textured choice; pictures both generated by the plan and sent by
 * hand (routes/sceneAI.js /api/mesh3d).
 *
 * One build = a background run with a status the page polls:
 *   1 plan      the local LLM (lib/llmChat.complete) answers lib/scenePlan.messages; parse + one retry that names the
 *               fault; clean -> a complete plan
 *   2 pictures  each "model" object: a picture (the page's image style) of it alone on white - an image job, in the queue
 *   3 models    each picture -> a .glb (lib/mesh3d.jobParams, mesh3d_worker.py) in the project's models3d/
 *   4 build     scripts/blend_scene.py build: <project>/blender/ai/<name>.blend (+ <name>.plan.json beside it)
 *   5 open      lib/blendView.open - the scene in the preview canvas, ready to edit and render to real
 * A picture or a model that fails does not stop the scene: that object is drawn as a stand-in of its kind and the
 * status says so. start() refuses a second build while one runs. */
"use strict";
const fs = require("fs");
const path = require("path");
const core = require("./core");
const SP = require("./scenePlan");
const mesh3d = require("./mesh3d");

const runs = new Map();
let active = null;
function bad(msg, status) { const e = new Error(msg); e.status = status || 400; return e; }
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function aiDir() { const d = path.join(core.projDir(core.getProject()), "blender", "ai"); fs.mkdirSync(d, { recursive: true }); return d; }

/** the image style for the pictures: the one asked for, else none (a refusal says so) */
function imageStyle(id) {
  const styles = require("./styles");
  const st = id ? styles.byId(core.STYLES_DIR, String(id)) : null;
  if (!st) return { error: "pick an image style first (Settings -> Image) - the detailed objects are drawn with it before they become 3D" };
  if (st.kind === "music" || st.kind === "video") return { error: `"${st.name}" is not an image style - pick one in Settings -> Image` };
  if (st.chain) return { error: `"${st.name}" is a ControlNet chain style - pick a plain image style for the pictures` };
  const miss = styles.missingSlots(st);
  if (miss.length) return { error: `style "${st.name}" is missing: ${miss.join(", ")}` };
  return { style: st };
}

/** wait for a queue job to finish -> the job (status done / failed / cancelled) */
async function waitJob(id, R, label, timeoutMs) {
  const t0 = Date.now();
  for (;;) {
    const j = core.jobs.get(id);
    if (!j) return { status: "failed", log: ["the job is gone"] };
    if (["done", "failed", "cancelled"].includes(j.status)) return j;
    if (R.cancel) { cancelJob(id); return { status: "cancelled", log: [] }; }
    if (Date.now() - t0 > (timeoutMs || 3 * 3600e3)) return { status: "failed", log: [`${label}: no answer in time`] };
    await sleep(R.poll || 700);
  }
}
const lastErr = (j) => { const l = (j.log || []).slice().reverse().find((x) => /ERROR|error|failed/i.test(String(x))); return l ? String(l).replace(/^\[worker\]\s*/, "").slice(0, 300) : j.status; };

function say(R, s) { R.lines.push(s); if (R.lines.length > 200) R.lines.shift(); }
/** the queue's own cancel (routes/index.js /api/jobs/:id/cancel) */
function cancelJob(id) {
  const job = core.jobs.get(id);
  if (!job || ["done", "failed", "cancelled"].includes(job.status)) return;
  job.status = "cancelled";
  try { core.killTree(job); } catch { /* not started */ }
  try { core.recordJob(job); } catch { /* fine */ }
}

async function askPlan(R, o) {
  const llmChat = require("./llmChat");
  const msgs = SP.messages(o.prompt, { seconds: o.seconds, maxModels: o.maxModels, models: o.models });
  let r = await (o.complete || llmChat.complete)(core, { messages: msgs, temperature: 0.4, max_tokens: o.max_tokens || 3000 });
  if (!r || !r.ok) throw bad("the LLM did not answer: " + ((r && r.error) || "no reply"), 502);
  let plan = SP.parse(r.text);
  if (!plan || !Array.isArray(plan.objects)) {
    say(R, "the LLM's answer was not a scene plan - asking again for the JSON alone");
    const again = msgs.concat([{ role: "assistant", content: String(r.text || "").slice(0, 4000) },
      { role: "user", content: "That was not the JSON plan. Reply with ONLY the JSON object, starting with { and ending with }." }]);
    r = await (o.complete || llmChat.complete)(core, { messages: again, temperature: 0.2, max_tokens: o.max_tokens || 3000 });
    plan = r && r.ok ? SP.parse(r.text) : null;
    if (!plan) throw bad("the LLM did not write a scene plan (twice) - try a clearer description, or another model in Settings -> LLM", 502);
  }
  return plan;
}

async function run(R, o) {
  const blendView = require("./blendView");
  try {
    // 1 the plan
    R.stage = "plan"; say(R, "1/5 the LLM is laying out the scene …");
    const raw = o.plan ? o.plan : await askPlan(R, o);
    const { plan, notes } = SP.clean(raw, { seconds: o.seconds, width: o.width, height: o.height, maxModels: o.maxModels, models: o.models });
    notes.forEach((n) => say(R, "plan: " + n));
    R.plan = plan;
    const want = plan.objects.filter((ob) => ob.kind === "model");
    say(R, `plan: "${plan.title}" - ${plan.objects.length} object(s)` + (want.length ? `, ${want.length} detailed model(s): ${want.map((w) => w.name).join(", ")}` : ""));
    // a new file every build (the same title twice = <name>_2): a scene saved back to ai/<name>.blend is never lost
    const base = require("./blendView").stemOf(o.name || plan.title);
    let stem = base;
    for (let k = 2; fs.existsSync(path.join(aiDir(), stem + ".blend")); k++) stem = `${base}_${k}`;
    R.stem = stem;
    // 2 + 3 pictures, then models
    if (want.length && o.models !== false) {
      const st = imageStyle(o.image_style_id);
      if (st.error) { say(R, "pictures: " + st.error + " - the detailed objects are drawn as stand-ins"); }
      else {
        R.stage = "pictures"; say(R, `2/5 drawing ${want.length} picture(s) with ${st.style.name} …`);
        const styles = require("./styles"), imageSeed = require("./imageSeed");
        const jobs = want.map((ob) => {
          const seed = imageSeed.forRequest(null);
          const job = core.makeJob({ mode: "image", prompt: `${ob.describe}, ${mesh3d.PICTURE_SUFFIX}`,
            style: styles.applyLoraWeights(st.style, null), style_id: st.style.id, style_name: st.style.name,
            width: 1024, height: 1024, batch: 1, seed: seed.seed, seed_random: seed.random,
            label: `✨ ${plan.title} · ${ob.name} (picture)` });
          job.chunk = { i: 0, n: 1 };
          R.jobs.push(job.id);
          return { ob, job };
        });
        for (const { ob, job } of jobs) {
          const j = await waitJob(job.id, R, ob.name);
          if (j.status === "done" && j.output) { ob.picture = path.join(core.pDir("output"), path.basename(j.output)); say(R, `picture: ${ob.name} -> ${path.basename(j.output)}`); }
          else say(R, `picture: ${ob.name} failed (${lastErr(j)}) - a stand-in ${ob.like}`);
          if (R.cancel) throw bad("stopped", 499);
        }
        R.stage = "models"; say(R, "3/5 turning the pictures into 3D models …");
        const m3d = require("./m3d");
        const mjobs = [];
        for (const ob of want.filter((x) => x.picture)) {
          const jp = mesh3d.jobParams({ picture: ob.picture, name: `${stem}_${ob.name}`, engine: o.engine, models_dir: m3d.dir(),
            label: `✨ ${plan.title} · ${ob.name} (3D model)` });
          if (jp.error) { say(R, `model: ${ob.name}: ${jp.error}`); continue; }
          const job = core.makeJob(jp.params);
          R.jobs.push(job.id);
          mjobs.push({ ob, job });
        }
        for (const { ob, job } of mjobs) {
          const j = await waitJob(job.id, R, ob.name);
          const name = j.status === "done" && j.output ? path.basename(j.output) : null;
          const file = name ? m3d.modelPath(name) : null;
          if (file) { ob.file = file; ob.model = name; say(R, `model: ${ob.name} -> models3d/${name}`); }
          else say(R, `model: ${ob.name} failed (${lastErr(j)}) - a stand-in ${ob.like}`);
          if (R.cancel) throw bad("stopped", 499);
        }
      }
    }
    // an "asset" names a model already in models3d/
    for (const ob of plan.objects.filter((x) => x.kind === "asset")) {
      const f = require("./m3d").modelPath(ob.asset);
      if (f) ob.file = f; else { say(R, `${ob.name}: models3d/${ob.asset} is not there - a box`); ob.kind = "box"; }
    }
    // 4 build
    R.stage = "build"; say(R, "4/5 Blender is building the scene …");
    const d = aiDir();
    const planFile = path.join(d, stem + ".plan.json");
    fs.writeFileSync(planFile, JSON.stringify({ ...plan, prompt: o.prompt || "" }, null, 1));
    const out = path.join(d, stem + ".blend");
    const r = await blendView.run(["build", planFile, out], (ln) => { if (typeof ln === "string" && /^H3B note /.test(ln)) say(R, "blender: " + ln.slice(9)); }, o.exe);
    if (r.error || !fs.existsSync(out)) throw bad("Blender could not build the scene: " + (r.error || "no file"), 500);
    // 5 open
    R.stage = "open"; say(R, "5/5 opening it in the preview …");
    R.scene = await blendView.open(out, { fresh: true, exe: o.exe });
    R.file = out;
    R.state = "done"; R.stage = "done";
    say(R, `✓ ${path.basename(out)} is open - look around, move things, then Render to real`);
  } catch (e) {
    R.state = R.cancel ? "cancelled" : "error"; R.error = String((e && e.message) || e);
    say(R, (R.cancel ? "stopped: " : "✗ ") + R.error);
  } finally {
    if (active === R.id) active = null;
  }
}

/** o = {prompt, seconds, engine (auto|hunyuan|trellis), models (bool), maxModels, image_style_id, width, height, name,
 *  plan (skip the LLM), complete / exe (tests)} -> {id} */
function start(o) {
  const x = o || {};
  if (!x.plan && !String(x.prompt || "").trim()) throw bad("describe the scene first");
  if (active && runs.get(active) && runs.get(active).state === "running") throw bad("a scene is already being built - wait for it or stop it", 409);
  const id = Math.random().toString(16).slice(2, 10);
  const R = { id, state: "running", stage: "plan", lines: [], jobs: [], plan: null, scene: null, error: null, started: Date.now(), prompt: String(x.prompt || "").slice(0, 2000) };
  runs.set(id, R);
  active = id;
  run(R, { ...x, seconds: x.seconds, engine: mesh3d.ENGINES.includes(x.engine) ? x.engine : "auto", models: x.models !== false });
  return { id, state: R.state };
}
function status(id) {
  const R = runs.get(String(id || active || ""));
  if (!R) return { state: "none" };
  return { id: R.id, state: R.state, stage: R.stage, lines: R.lines.slice(-60), jobs: R.jobs, error: R.error, file: R.file || null,
           plan: R.plan ? { title: R.plan.title, objects: R.plan.objects.map((ob) => ({ name: ob.name, kind: ob.kind, model: ob.model || null })) } : null,
           scene: R.state === "done" ? R.scene : null };
}
function stop(id) {
  const R = runs.get(String(id || active || ""));
  if (!R || R.state !== "running") return { ok: false };
  R.cancel = true;
  for (const j of R.jobs) cancelJob(j);
  return { ok: true };
}

module.exports = { start, status, stop, imageStyle, aiDir };
